edits.before:
onKeydown (event) {
  if (event.keyCode === 27) this.closeModal(event) // esc
  if (event.keyCode === 9) this.retainFocus(event) // tab
}

edits.after:
onKeydown (event) {
  if (event.keyCode === 32) { return; } // ignore space
  if (event.keyCode === 27) this.closeModal(event) // esc
  if (event.keyCode === 9) this.retainFocus(event) // tab
}
